    "question": "期間10日のプロジェクトを,5日目の終了時にアーンドバリュー分析したところ,表のとおりであった。現在のコスト効率が今後も続く場合,完成時総コスト見積り(EAC)は何万円か。\n\n[管理項目 金額(万円)]\n完成時総予算(BAC):100\nプランドバリュー(PV):50\nアーンドバリュー(EV):40\n実コスト(AC):60",
