    "question": "システムの改善に向けて提出された案1〜4について、評価項目を設定して採点した結果を、採点結果表に示す。効果及びリスクについては5段階評価とし、それぞれの評価項目の重要度に応じて、重み付け表に示すとおりの重み付けを行った上で、次の式で総合評価点を算出する。総合評価点が最も高い改善案はどれか。\n\n[総合評価点の算出式]\n総合評価点 = 効果の総評価点 − リスクの総評価点\n\n[採点結果表]\n評価項目 | 案1 | 案2 | 案3 | 案4\n作業コスト削減(効果) | 5 | 4 | 2 | 4\nシステム運用品質向上(効果) | 2 | 4 | 2 | 5\nセキュリティ強化(効果) | 3 | 4 | 5 | 2\n技術リスク(リスク) | 4 | 1 | 5 | 1\nスケジュールリスク(リスク) | 2 | 4 | 1 | 5\n\n[重み付け表]\n評価項目 | 重み\n作業コスト削減 | 3\nシステム運用品質向上 | 2\nセキュリティ強化 | 4\n技術リスク | 3\nスケジュールリスク | 8",
