    "question": "システムの信頼性を測る指標の一つに稼働品質率がある。年間の稼働品質率で評価される信頼性が最も高いシステムはどれか。ここで、稼働品質率は次の式で算出し、システムの資産規模には総運用費用を用いるものとする。\n稼働品質率 = 利用者に迷惑を掛けた回数(オンライン処理回数+バッチ処理回数) ÷ システムの資産規模(総運用費用)\n[表:システム, 迷惑を掛けた回数(オンライン処理・バッチ処理、単位:回/年), 総運用費用(百万円/年)]\nシステムA: オンライン処理3、バッチ処理12、総運用費用120\nシステムB: オンライン処理4、バッチ処理8、総運用費用100\nシステムC: オンライン処理6、バッチ処理2、総運用費用80\nシステムD: オンライン処理6、バッチ処理3、総運用費用60",
